static void ipa_filter_tuple_zero ( struct ipa_endpoint * endpoint ) { u32 endpoint_id = endpoint -> endpoint_id ; struct ipa * ipa = endpoint -> ipa ; const struct reg * reg ; u32 offset ; u32 val ; if ( ipa -> version < IPA_VERSION_5_0 ) { reg = ipa_reg ( ipa , ENDP_FILTER_ROUTER_HSH_CFG ) ; offset = reg_n_offset ( reg , endpoint_id ) ; val = ioread32 ( endpoint -> ipa -> reg_virt + offset ) ; } else { reg = ipa_reg ( ipa , ENDP_FILTER_CACHE_CFG ) ; offset = reg_n_offset ( reg , endpoint_id ) ; val = 0 ; } iowrite32 ( val , endpoint -> ipa -> reg_virt + offset ) ; } 